import React from 'react';
import { renderHook, act } from '@testing-library/react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { IntlProvider } from 'react-intl';
import type { SyntheticEvent } from 'react';
import { useWishlistAuthDrawer } from './useWishlistAuthDrawer';
import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
import { useCustomerType } from '@salesforce/commerce-sdk-react';
import {
  getSessionJSONItem,
  setSessionJSONItem,
  clearSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';

// Hoisted so the mock factory below (which vi.mock hoists above these imports) can reference
// it — a plain `const` here would not yet be initialised at that point.
const { mockAuthorizeIDPMutateAsync, mockMergeBasketMutate, mockCapBasketQuantities } = vi.hoisted(() => ({
  mockAuthorizeIDPMutateAsync: vi.fn(),
  mockMergeBasketMutate: vi.fn(),
  mockCapBasketQuantities: vi.fn(),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useCustomerType: vi.fn(),
  AuthHelpers: {
    AuthorizePasswordless: 'AuthorizePasswordless',
    LoginPasswordlessUser: 'LoginPasswordlessUser',
    AuthorizeIDP: 'AuthorizeIDP',
  },
  // AuthorizeIDP's mutateAsync is individually controllable (tests simulate it rejecting
  // before any redirect happens) — the other two helpers don't need per-test control.
  useAuthHelper: (helper: string) =>
    helper === 'AuthorizeIDP' ? { mutateAsync: mockAuthorizeIDPMutateAsync } : { mutateAsync: vi.fn() },
  // Mocked by its real export name — the hook under test imports this aliased locally as
  // `useShopperBasketsMutation`, but the module actually exports `useShopperBasketsV2Mutation`.
  useShopperBasketsV2Mutation: () => ({ mutate: mockMergeBasketMutate }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-customer', () => ({
  useCurrentCustomer: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-auth-modal', () => ({
  useAuthModal: () => ({ isOpen: false, onOpen: vi.fn(), onClose: vi.fn() }),
  REGISTER_VIEW: 'register',
}));

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: () => ({
    app: {
      login: {
        passwordless: { enabled: true, mode: 'callback' },
        social: { enabled: true, idps: ['apple', 'google'], redirectURI: '/callback' },
      },
    },
  }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-app-origin', () => ({
  useAppOrigin: () => 'https://localhost:3000',
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: () => ({ locale: { id: 'en-AU' } }),
}));

vi.mock('@salesforce/retail-react-app/app/utils/auth-utils', () => ({
  getAuthorizePasswordlessErrorMessage: vi.fn(() => ({ id: 'err', defaultMessage: 'Error' })),
  getLoginPasswordlessErrorMessage: vi.fn(() => ({ id: 'err', defaultMessage: 'Error' })),
  getPasswordlessCallbackUrl: vi.fn((uri: string) => uri),
}));

vi.mock('@salesforce/retail-react-app/app/utils/utils', () => ({
  setSessionJSONItem: vi.fn(),
  getSessionJSONItem: vi.fn(() => null),
  clearSessionJSONItem: vi.fn(),
  buildRedirectURI: vi.fn((origin: string, path: string) => origin + path),
  noop: vi.fn(),
}));

vi.mock('app/hooks/useUiCopy', () => ({
  useUiCopy: () => ({ t: (_key: string, fallback: string) => fallback, isLoading: false }),
}));

// SFCC-250 step 4.2: this file tests useWishlistAuthDrawer's own wiring contract (does it call
// capBasketQuantities, with the merged basket, once the merge succeeds) — not
// useCartMergeAndCap's own cap/guard behaviour, which is already covered by that hook's own
// useCartMergeAndCap.test.ts. Mocked at the smallest surface for the same reason mergeBasket
// itself is mocked below, rather than exercised for real.
vi.mock('app/hooks/useCartMergeAndCap', () => ({
  useCartMergeAndCap: () => ({ capBasketQuantities: mockCapBasketQuantities }),
}));

const mockUseCurrentCustomer = vi.mocked(useCurrentCustomer);
const mockUseCustomerType = vi.mocked(useCustomerType);
const mockGetSessionJSONItem = vi.mocked(getSessionJSONItem);
const mockSetSessionJSONItem = vi.mocked(setSessionJSONItem);
const mockClearSessionJSONItem = vi.mocked(clearSessionJSONItem);

function mockGuest() {
  mockUseCurrentCustomer.mockReturnValue({ data: { isRegistered: false } } as ReturnType<typeof useCurrentCustomer>);
  mockUseCustomerType.mockReturnValue({ isRegistered: false } as ReturnType<typeof useCustomerType>);
}

function mockRegistered() {
  mockUseCurrentCustomer.mockReturnValue({ data: { isRegistered: true } } as ReturnType<typeof useCurrentCustomer>);
  mockUseCustomerType.mockReturnValue({ isRegistered: true } as ReturnType<typeof useCustomerType>);
}

const TEST_INTENT_ID = 'test-wishlist-intent';

// onSignInWithApple/onSignInWithGoogle are typed `() => void` (matching the onClick contract
// they're ultimately bound to in SocialButtons) even though the real implementation is async —
// this cast lets tests await the underlying promise so state updates land before assertions run.
const invokeSocialSignIn = (fn?: () => void): Promise<void> =>
  Promise.resolve((fn as (() => Promise<void>) | undefined)?.());

const makeSyntheticEvent = () =>
  ({ currentTarget: document.createElement('button') } as unknown as SyntheticEvent<HTMLElement>);

const wrapper = ({ children }: { children: React.ReactNode }) => (
  <IntlProvider locale="en-AU" defaultLocale="en-AU">
    {children}
  </IntlProvider>
);

describe('useWishlistAuthDrawer', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockGuest();
  });

  test('starts with the drawer closed', () => {
    const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

    expect(result.current.isOpen).toBe(false);
  });

  describe('handleTriggerClick — auth gate', () => {
    test('guest: opens the drawer', () => {
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });

      expect(result.current.isOpen).toBe(true);
    });

    test('registered: calls onAuthSuccess without opening the drawer', () => {
      mockRegistered();
      const onAuthSuccess = vi.fn();
      const { result } = renderHook(() => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }), {
        wrapper,
      });

      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });

      expect(onAuthSuccess).toHaveBeenCalledTimes(1);
      expect(result.current.isOpen).toBe(false);
    });

    test('registered with no onAuthSuccess: does not throw', () => {
      mockRegistered();
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      expect(() => {
        act(() => {
          result.current.handleTriggerClick(makeSyntheticEvent());
        });
      }).not.toThrow();
    });
  });

  describe('handleDrawerClose', () => {
    test('closes the drawer and resets emailValue', () => {
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });
      expect(result.current.isOpen).toBe(true);

      act(() => {
        result.current.onEmailChange('test@example.com');
      });
      expect(result.current.emailValue).toBe('test@example.com');

      act(() => {
        result.current.handleDrawerClose();
      });

      expect(result.current.isOpen).toBe(false);
      expect(result.current.emailValue).toBe('');
    });
  });

  describe('auto-close effect', () => {
    test('closes drawer and fires onAuthSuccess when isRegistered transitions to true', () => {
      const onAuthSuccess = vi.fn();
      const { result, rerender } = renderHook(
        () => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }),
        { wrapper },
      );

      // Open the drawer as guest
      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });
      expect(result.current.isOpen).toBe(true);

      // Simulate login completing — customer becomes registered
      mockRegistered();
      rerender();

      expect(result.current.isOpen).toBe(false);
      expect(onAuthSuccess).toHaveBeenCalledTimes(1);
    });
  });

  describe('passwordless success — basket merge (SFCC-250)', () => {
    // The merge lives in the same isRegistered-flip effect as the auto-close behaviour above
    // (see the effect's own comment for why) — mockRegistered() + rerender() is this test
    // file's existing way of simulating "a login mutation just resolved and isRegistered
    // caught up", used the same way by the 'auto-close effect' describe block above.
    test('merges the guest basket exactly once, with sum_quantities and createDestinationBasket, when isRegistered transitions to true while the drawer is open', () => {
      const { result, rerender } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), {
        wrapper,
      });

      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });
      expect(result.current.isOpen).toBe(true);

      mockRegistered();
      rerender();

      expect(mockMergeBasketMutate).toHaveBeenCalledTimes(1);
      // SFCC-250 step 4.2 added a second (options) argument carrying onSuccess — asserted
      // structurally as "a function" here, since its own behaviour (calling
      // capBasketQuantities) is covered by the dedicated test below, not this one. The first
      // argument's shape is unchanged from before that step.
      const [variables, options] = mockMergeBasketMutate.mock.calls[0];
      expect(variables).toEqual({
        headers: { 'Content-Type': 'application/json' },
        parameters: {
          createDestinationBasket: true,
          productItemMergeMode: 'sum_quantities',
        },
      });
      expect(options?.onSuccess).toEqual(expect.any(Function));
    });

    test('SFCC-250 step 4.2: calls capBasketQuantities with the merged basket once the merge mutation succeeds, and not before', () => {
      const { result, rerender } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), {
        wrapper,
      });

      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });

      mockRegistered();
      rerender();

      expect(mockMergeBasketMutate).toHaveBeenCalledTimes(1);
      expect(mockCapBasketQuantities).not.toHaveBeenCalled();

      // Simulate React Query invoking the merge mutation's onSuccess callback with the
      // resolved, merged basket — mockMergeBasketMutate is a bare vi.fn() and does not do this
      // automatically, matching this file's existing style of manually driving mocked async SDK
      // callbacks (see the social sign-in describe block below).
      const onSuccess = mockMergeBasketMutate.mock.calls[0][1]?.onSuccess as (basket: unknown) => void;
      const fakeMergedBasket = { basketId: 'merged-basket-id', productItems: [] };
      act(() => {
        onSuccess(fakeMergedBasket);
      });

      expect(mockCapBasketQuantities).toHaveBeenCalledTimes(1);
      expect(mockCapBasketQuantities).toHaveBeenCalledWith(fakeMergedBasket);
    });
  });

  describe('create-account route', () => {
    test('does not merge when isRegistered later transitions to true — a new customer has no prior basket', () => {
      const { result, rerender } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), {
        wrapper,
      });

      // Open the drawer as guest, then take the create-account path — this closes the
      // wishlist drawer (handleDrawerClose) before handing off to SFCC's own register modal.
      act(() => {
        result.current.handleTriggerClick(makeSyntheticEvent());
      });
      act(() => {
        result.current.onCreateAccount();
      });
      expect(result.current.isOpen).toBe(false);

      // Registration completing flips isRegistered the same way a passwordless success
      // would — but with both isOpen and isOtpAuthOpen already false, the merge-owning
      // effect's own condition must not be satisfied.
      mockRegistered();
      rerender();

      expect(mockMergeBasketMutate).not.toHaveBeenCalled();
    });
  });

  describe('pending intent restoration (social IDP redirect)', () => {
    test("registered customer with a matching stored intent: clears the flag and fires onAuthSuccess once, without a second merge on top of social-login-redirect's own", () => {
      mockRegistered();
      // Simulate a pending intent written to sessionStorage before the social redirect.
      mockGetSessionJSONItem.mockReturnValueOnce({ intentId: TEST_INTENT_ID, timestamp: Date.now() });
      const onAuthSuccess = vi.fn();

      renderHook(() => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }), { wrapper });

      expect(mockClearSessionJSONItem).toHaveBeenCalledTimes(1);
      expect(onAuthSuccess).toHaveBeenCalledTimes(1);
      // This hook's social-IDP path is a separate, pre-existing effect (isOpen/isOtpAuthOpen
      // are both false throughout a full-page-redirect round trip) — the isRegistered-flip
      // effect that owns the new merge call must not fire here. Base's own
      // social-login-redirect already performs the real merge for this route, outside this
      // hook entirely.
      expect(mockMergeBasketMutate).not.toHaveBeenCalled();
    });

    test('registered customer with no stored intent: does not fire onAuthSuccess', () => {
      mockRegistered();
      // getSessionJSONItem returns null by default — no pending intent.
      const onAuthSuccess = vi.fn();

      renderHook(() => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }), { wrapper });

      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
      expect(onAuthSuccess).not.toHaveBeenCalled();
    });

    test('guest customer with stored intent: does not fire onAuthSuccess', () => {
      // isRegistered is false — effect should early-return before ever reading the intent.
      // Deliberately not queuing a mockReturnValueOnce here: since the effect must never call
      // getSessionJSONItem on this path, a queued value would never be consumed and would
      // silently leak into whichever test runs next.
      const onAuthSuccess = vi.fn();

      renderHook(() => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }), { wrapper });

      expect(mockGetSessionJSONItem).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
      expect(onAuthSuccess).not.toHaveBeenCalled();
    });

    test('registered customer with a stored intent from a different instance: leaves the flag and does not fire', () => {
      // e.g. the header and a PDP both mount their own instance on the page the shopper
      // returns to — only the instance whose intentId initiated the redirect may consume it.
      mockRegistered();
      mockGetSessionJSONItem.mockReturnValueOnce({ intentId: 'some-other-instance', timestamp: Date.now() });
      const onAuthSuccess = vi.fn();

      renderHook(() => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }), { wrapper });

      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
      expect(onAuthSuccess).not.toHaveBeenCalled();
    });

    test('registered customer with an expired stored intent: clears it but does not fire', () => {
      // A cancelled/abandoned IDP round-trip has no explicit failure signal this hook can
      // observe — age-based expiry (5 minutes) bounds how long a stale intent can linger.
      mockRegistered();
      const TEN_MINUTES_MS = 10 * 60 * 1000;
      mockGetSessionJSONItem.mockReturnValueOnce({
        intentId: TEST_INTENT_ID,
        timestamp: Date.now() - TEN_MINUTES_MS,
      });
      const onAuthSuccess = vi.fn();

      renderHook(() => useWishlistAuthDrawer({ onAuthSuccess, intentId: TEST_INTENT_ID }), { wrapper });

      expect(mockClearSessionJSONItem).toHaveBeenCalledTimes(1);
      expect(onAuthSuccess).not.toHaveBeenCalled();
    });
  });

  describe('social IDP sign-in', () => {
    test('onSignInWithApple stores the intent bound to this instance before redirecting', async () => {
      mockAuthorizeIDPMutateAsync.mockResolvedValueOnce(undefined);
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      await act(async () => {
        await invokeSocialSignIn(result.current.onSignInWithApple);
      });

      expect(mockSetSessionJSONItem).toHaveBeenCalledWith(
        'zimmPendingWishlistAction',
        expect.objectContaining({ intentId: TEST_INTENT_ID }),
      );
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });

    test('onSignInWithApple clears the just-stored intent when authorizeIDP rejects before navigating', async () => {
      mockAuthorizeIDPMutateAsync.mockRejectedValueOnce(new Error('network error'));
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      await act(async () => {
        await invokeSocialSignIn(result.current.onSignInWithApple);
      });

      expect(mockClearSessionJSONItem).toHaveBeenCalledWith('zimmPendingWishlistAction');
      expect(result.current.socialError).toBeDefined();
    });

    test('onSignInWithGoogle clears the just-stored intent when authorizeIDP rejects before navigating', async () => {
      mockAuthorizeIDPMutateAsync.mockRejectedValueOnce(new Error('network error'));
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      await act(async () => {
        await invokeSocialSignIn(result.current.onSignInWithGoogle);
      });

      expect(mockClearSessionJSONItem).toHaveBeenCalledWith('zimmPendingWishlistAction');
      expect(result.current.socialError).toBeDefined();
    });
  });

  describe('returned values', () => {
    test('drawerTitle returns the formatted message default', () => {
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      expect(result.current.drawerTitle).toBe('Wishlist');
    });

    test('isSocialEnabled reflects the login config', () => {
      const { result } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), { wrapper });

      expect(result.current.isSocialEnabled).toBe(true);
    });
  });
});

